from __future__ import annotations


DASHBOARD_HTML = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>pyPaperclip / Operator Console</title>
<style>
:root{color-scheme:dark;--bg:#0b1020;--panel:#121a2b;--panel2:#18233a;--line:#263451;--text:#eef4ff;--muted:#93a4c3;--cyan:#63e6e2;--amber:#ffcc66;--red:#ff7b8b;--green:#78e08f;--shadow:0 18px 50px #0004}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 80% -10%,#243b66 0,#0b1020 45%);color:var(--text);font:14px/1.5 Inter,ui-sans-serif,system-ui,sans-serif}button,input{font:inherit}.shell{display:grid;grid-template-columns:240px 1fr;min-height:100vh}.side{border-right:1px solid var(--line);padding:28px 18px;background:#0b1222cc;backdrop-filter:blur(16px)}.brand{font-weight:800;font-size:20px;letter-spacing:-.04em;margin-bottom:8px}.brand span{color:var(--cyan)}.sub{color:var(--muted);font-size:12px;margin-bottom:34px}.nav{display:grid;gap:7px}.nav button,.ghost{background:transparent;border:1px solid transparent;color:var(--muted);text-align:left;border-radius:10px;padding:10px 12px;cursor:pointer}.nav button:hover,.nav button.active,.ghost:hover{background:var(--panel2);color:var(--text);border-color:var(--line)}.main{padding:30px;max-width:1500px;width:100%;margin:auto}.top{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;margin-bottom:26px}.eyebrow{text-transform:uppercase;letter-spacing:.15em;font-size:11px;color:var(--cyan);font-weight:700}.headline{font-size:32px;line-height:1.1;margin:5px 0 6px;letter-spacing:-.05em}.muted{color:var(--muted)}.actions{display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end}.input{border:1px solid var(--line);background:var(--panel);color:var(--text);border-radius:9px;padding:9px 11px;min-width:230px}.primary{border:0;border-radius:9px;padding:10px 14px;background:var(--cyan);color:#07131d;font-weight:800;cursor:pointer}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:16px}.card{background:linear-gradient(150deg,#16233b,#10182a);border:1px solid var(--line);border-radius:16px;padding:18px;box-shadow:var(--shadow)}.label{font-size:12px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}.value{font-size:30px;font-weight:800;letter-spacing:-.05em;margin-top:8px}.accent{color:var(--cyan)}.warning{color:var(--amber)}.danger{color:var(--red)}.columns{display:grid;grid-template-columns:1.2fr .8fr;gap:16px}.card h2{font-size:16px;margin:0 0 14px}.table-wrap{overflow:auto}.table{width:100%;border-collapse:collapse}.table th,.table td{text-align:left;border-bottom:1px solid var(--line);padding:11px 8px;white-space:nowrap}.table th{font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}.pill{display:inline-flex;border-radius:99px;padding:3px 8px;font-size:11px;font-weight:700;background:var(--panel2);color:var(--muted)}.pill.done{color:var(--green)}.pill.running{color:var(--cyan)}.pill.failed,.pill.blocked{color:var(--red)}.pill.pending_approval{color:var(--amber)}.log{display:grid;gap:8px;max-height:390px;overflow:auto}.event{padding:10px 12px;background:#0e1729;border:1px solid var(--line);border-radius:10px}.event strong{font-size:12px}.event small{display:block;color:var(--muted);margin-top:2px}.empty{padding:25px 0;color:var(--muted);text-align:center}.toast{position:fixed;bottom:20px;right:20px;background:var(--panel2);border:1px solid var(--line);border-radius:10px;padding:12px 15px;display:none}.help{margin-top:18px;padding:12px;background:#13243a;border:1px dashed #355278;border-radius:10px;color:var(--muted);font-size:12px}@media(max-width:900px){.shell{display:block}.side{border-right:0;border-bottom:1px solid var(--line)}.nav{display:flex;overflow:auto}.main{padding:20px}.grid{grid-template-columns:repeat(2,1fr)}.columns{grid-template-columns:1fr}.top{display:block}.actions{justify-content:flex-start;margin-top:16px}}@media(max-width:520px){.grid{grid-template-columns:1fr}.headline{font-size:26px}}
</style></head>
<body><div class="shell"><aside class="side"><div class="brand">py<span>Paperclip</span></div><div class="sub">operator console · v0.5</div><nav class="nav"><button class="active" data-view="overview">Overview</button><button data-view="tasks">Tasks</button><button data-view="agents">Agents</button><button data-view="audit">Audit trail</button></nav><div class="help">Paste an owner, admin, operator, or viewer API key above. It is kept only in this browser's local storage.</div></aside><main class="main"><header class="top"><div><div class="eyebrow">Control plane / live workspace</div><h1 class="headline">Operator overview</h1><div class="muted" id="stamp">Waiting for API key</div></div><div class="actions"><input id="key" class="input" type="password" placeholder="ppk_… API key"><button id="save" class="primary">Connect</button><button id="refresh" class="ghost">Refresh</button></div></header><section class="grid"><div class="card"><div class="label">Companies</div><div id="companies" class="value accent">—</div></div><div class="card"><div class="label">Active agents</div><div id="agents" class="value">—</div></div><div class="card"><div class="label">Queued / running</div><div id="queue" class="value warning">—</div></div><div class="card"><div class="label">Failed / blocked</div><div id="failed" class="value danger">—</div></div></section><section class="columns"><div class="card"><h2>Recent tasks</h2><div class="table-wrap"><table class="table"><thead><tr><th>Title</th><th>Company</th><th>State</th><th>Updated</th></tr></thead><tbody id="taskRows"></tbody></table></div></div><div class="card"><h2>Audit stream</h2><div id="events" class="log"></div></div></section></main></div><div id="toast" class="toast"></div>
<script>
const $=id=>document.getElementById(id); const state={key:localStorage.getItem('pypaperclip_api_key')||''}; $('key').value=state.key;
function toast(msg){$('toast').textContent=msg;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',2800)}
async function api(path){const r=await fetch(path,{headers:state.key?{'X-API-Key':state.key}:{}});if(!r.ok)throw new Error((await r.json().catch(()=>({}))).detail||`HTTP ${r.status}`);return r.json()}
function pill(s){return `<span class="pill ${s}">${s.replaceAll('_',' ')}</span>`}
async function load(){if(!state.key){$('stamp').textContent='Enter an API key to connect';return}try{const companies=await api('/companies?limit=200');let agents=0,queue=0,failed=0,tasks=[],events=[];for(const c of companies.items){const a=await api(`/companies/${c.id}/agents?limit=200`);agents+=a.items.filter(x=>x.status==='active').length;const t=await api(`/companies/${c.id}/tasks?limit=100&offset=0`);tasks.push(...t.items.map(x=>({...x,company:c.name})));queue+=t.items.filter(x=>['queued','running'].includes(x.status)).length;failed+=t.items.filter(x=>['failed','blocked'].includes(x.status)).length;const e=await api(`/audit?company_id=${c.id}&limit=8`);events.push(...e.items.map(x=>({...x,company:c.name})))}$('companies').textContent=companies.total;$('agents').textContent=agents;$('queue').textContent=queue;$('failed').textContent=failed;tasks.sort((a,b)=>b.updated_at.localeCompare(a.updated_at));$('taskRows').innerHTML=tasks.slice(0,12).map(x=>`<tr><td>${escapeHtml(x.title)}</td><td>${escapeHtml(x.company)}</td><td>${pill(x.status)}</td><td>${new Date(x.updated_at).toLocaleString()}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No tasks yet</td></tr>';events.sort((a,b)=>b.id-a.id);$('events').innerHTML=events.slice(0,12).map(x=>`<div class="event"><strong>${escapeHtml(x.event)}</strong><small>${escapeHtml(x.company)} · ${new Date(x.created_at).toLocaleString()}</small></div>`).join('')||'<div class="empty">No audit events yet</div>';$('stamp').textContent=`Connected · refreshed ${new Date().toLocaleTimeString()}`}catch(e){$('stamp').textContent='Connection failed';toast(e.message)}}
function escapeHtml(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
$('save').onclick=()=>{state.key=$('key').value.trim();localStorage.setItem('pypaperclip_api_key',state.key);load()};$('refresh').onclick=load;document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-view]').forEach(x=>x.classList.remove('active'));b.classList.add('active');toast(`${b.textContent} view uses the live overview feed`)});if(state.key)load();setInterval(()=>state.key&&load(),30000);
</script></body></html>'''
